-- POCHEMUCHKA MVP curriculum v2: synchronize Supabase with src/content/content.ts.
-- Exact curriculum: 12 active lessons / 200 quiz activities.
-- Grade routing: 4-6 -> 1, 7-8 -> 2, 9-10 -> 3.
-- Safe for existing users: legacy lessons are deactivated, not deleted.

on conflict(id) do update set title=excluded.title,description=excluded.description,icon=excluded.icon,order_index=excluded.order_index,is_active=excluded.is_active;

on conflict(id) do update set world_id=excluded.world_id,title=excluded.title,description=excluded.description,order_index=excluded.order_index;

update lessons set is_active=false where topic_id in ('world-basics','animals-basics','languages-basics','math-basics');


on conflict(id) do update set lesson_id=excluded.lesson_id,type=excluded.type,order_index=excluded.order_index,content=excluded.content,config=excluded.config;

update lessons set is_active=(id in ('nature-1','nature-2','nature-3','animals-1','animals-2','animals-3','language-1','language-2','language-3','math-1','math-2','math-3')) where topic_id in ('world-basics','animals-basics','languages-basics','math-basics');

do $$
declare v_lessons int; v_activities int; v_bad_lessons int; v_bad_activities int;
begin
 select count(*) into v_lessons from lessons where is_active and topic_id in ('world-basics','animals-basics','languages-basics','math-basics');
 select count(*) into v_activities from activities a join lessons l on l.id=a.lesson_id where l.is_active and a.type='quiz';
 select count(*) into v_bad_lessons from lessons where is_active and topic_id in ('world-basics','animals-basics','languages-basics','math-basics') and not ((age_min=4 and age_max=6 and difficulty=1) or (age_min=7 and age_max=8 and difficulty=2) or (age_min=9 and age_max=10 and difficulty=3));
 select count(*) into v_bad_activities from activities a join lessons l on l.id=a.lesson_id where l.is_active and (a.type <> 'quiz' or jsonb_array_length(coalesce(a.content->'answers','[]'::jsonb)) <> 3 or a.content->>'correctAnswerId' <> '0');
 if v_lessons <> 12 or v_activities <> 200 or v_bad_lessons <> 0 or v_bad_activities <> 0 then raise exception 'POCHEMUCHKA curriculum integrity failed: lessons=%, activities=%, bad_lessons=%, bad_activities=%',v_lessons,v_activities,v_bad_lessons,v_bad_activities; end if;
end $$;
