insert into lessons(id,topic_id,title,description,age_min,age_max,difficulty,learning_goal,order_index,is_active) values
('nature-1','world-basics','Природа: Узнай и пойми','Наблюдаем природные явления и времена года.',4,6,1, '["узнавать и понимать базовые понятия"]'::jsonb,1,true),
('nature-2','world-basics','Природа: Пойми почему','Ищем причины и связи в природных явлениях.',7,8,2, '["объяснять причины и связи"]'::jsonb,2,true),
('nature-3','world-basics','Природа: Объясни и примени','Разбираем природные процессы и их взаимосвязи.',9,10,3, '["объяснять процессы и применять знания"]'::jsonb,3,true),
('animals-1','animals-basics','Растения и животные: Узнай и пойми','Знакомимся с особенностями живых организмов.',4,6,1, '["узнавать и понимать базовые понятия"]'::jsonb,1,true),
('animals-2','animals-basics','Растения и животные: Пойми почему','Разбираемся, как живые организмы получают пищу и приспосабливаются.',7,8,2, '["объяснять причины и связи"]'::jsonb,2,true),
('animals-3','animals-basics','Растения и животные: Объясни и примени','Изучаем пищевые связи, приспособления и экосистемы.',9,10,3, '["объяснять процессы и применять знания"]'::jsonb,3,true),
('language-1','languages-basics','Язык и чтение: Узнай и пойми','Учимся замечать буквы, слова и простые правила.',4,6,1, '["узнавать и понимать базовые понятия"]'::jsonb,1,true),
('language-2','languages-basics','Язык и чтение: Пойми почему','Разбираемся в тексте, словах и выразительном чтении.',7,8,2, '["объяснять причины и связи"]'::jsonb,2,true),
('language-3','languages-basics','Язык и чтение: Объясни и примени','Изучаем части речи и литературные понятия.',9,10,3, '["объяснять процессы и применять знания"]'::jsonb,3,true),
('math-1','math-basics','Математика: Узнай и пойми','Осваиваем базовые числа, действия и величины.',4,6,1, '["узнавать и понимать базовые понятия"]'::jsonb,1,true),
('math-2','math-basics','Математика: Пойми почему','Учимся видеть закономерности и объяснять математические правила.',7,8,2, '["объяснять причины и связи"]'::jsonb,2,true),
('math-3','math-basics','Математика: Объясни и примени','Решаем задачи и применяем математические понятия.',9,10,3, '["объяснять процессы и применять знания"]'::jsonb,3,true)\non conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,age_min=excluded.age_min,age_max=excluded.age_max,difficulty=excluded.difficulty,learning_goal=excluded.learning_goal,order_index=excluded.order_index,is_active=excluded.is_active;
insert into activities(id,lesson_id,type,order_index,content,config) values
('nature-1-01','nature-1','quiz',1,'{"question":"Почему зимой идёт снег, а летом чаще дождь?","answers":[{"id":"0","text":"Зимой холодно, поэтому вода может замерзать в снежинки."},{"id":"1","text":"Потому что зимой Солнце исчезает"},{"id":"2","text":"Потому что летом нет облаков"}],"correctAnswerId":"0","explanation":"При достаточно низкой температуре вода в облаках замерзает и образует снежинки."}'::jsonb,'{"xp":10}'::jsonb),
('nature-1-02','nature-1','quiz',2,'{"question":"Почему осенью листья желтеют и опадают?","answers":[{"id":"0","text":"Становится холоднее и меньше света, поэтому дерево перестраивает свою работу."},{"id":"1","text":"Листья становятся тяжелее"},{"id":"2","text":"Дерево начинает цвести зимой"}],"correctAnswerId":"0","explanation":"Осенью деревья готовятся к зиме и прекращают поддерживать листья так, как летом."}'::jsonb,'{"xp":10}'::jsonb),
('nature-1-03','nature-1','quiz',3,'{"question":"Почему появляется радуга?","answers":[{"id":"0","text":"Солнечный свет проходит через капли воды и разделяется на цвета."},{"id":"1","text":"Облака окрашивают небо"},{"id":"2","text":"Снег отражает цвета"}],"correctAnswerId":"0","explanation":"Капли воды преломляют и разделяют солнечный свет на разные цвета."}'::jsonb,'{"xp":10}'::jsonb),
('nature-1-04','nature-1','quiz',4,'{"question":"Куда улетают перелётные птицы осенью?","answers":[{"id":"0","text":"Туда, где зимой теплее и достаточно пищи."},{"id":"1","text":"Только на вершины гор"},{"id":"2","text":"Под землю"}],"correctAnswerId":"0","explanation":"Птицы перемещаются туда, где условия подходят для зимовки."}'::jsonb,'{"xp":10}'::jsonb),
('nature-1-05','nature-1','quiz',5,'{"question":"Что такое ветер?","answers":[{"id":"0","text":"Движение воздуха."},{"id":"1","text":"Движение воды"},{"id":"2","text":"Движение облаков без воздуха"}],"correctAnswerId":"0","explanation":"Ветер — это движение воздуха относительно поверхности Земли."}'::jsonb,'{"xp":10}'::jsonb),
('nature-1-06','nature-1','quiz',6,'{"question":"Что мы обычно видим раньше во время грозы — молнию или гром?","answers":[{"id":"0","text":"Молнию."},{"id":"1","text":"Гром"},{"id":"2","text":"Они всегда появляются одновременно"}],"correctAnswerId":"0","explanation":"Свет от молнии достигает нас быстрее, чем звук грома."}'::jsonb,'{"xp":10}'::jsonb),
('nature-1-07','nature-1','quiz',7,'{"question":"Откуда берутся облака?","answers":[{"id":"0","text":"Вода испаряется, поднимается, охлаждается и превращается в маленькие капельки."},{"id":"1","text":"Из дыма деревьев"},{"id":"2","text":"Из растаявшего снега прямо в небе"}],"correctAnswerId":"0","explanation":"Водяной пар охлаждается и превращается в капельки воды или кристаллы льда."}'::jsonb,'{"xp":10}'::jsonb),
('nature-1-08','nature-1','quiz',8,'{"question":"Почему весной тает снег?","answers":[{"id":"0","text":"Воздух становится теплее, и снег начинает таять."},{"id":"1","text":"Потому что снег становится тяжелее"},{"id":"2","text":"Потому что ветер превращает его в дождь"}],"correctAnswerId":"0","explanation":"При повышении температуры лёд и снег переходят в жидкую воду."}'::jsonb,'{"xp":10}'::jsonb),
('nature-1-09','nature-1','quiz',9,'{"question":"Зачем природе нужен дождь?","answers":[{"id":"0","text":"Он приносит воду растениям, животным, рекам и озёрам."},{"id":"1","text":"Чтобы сделать воздух сухим"},{"id":"2","text":"Чтобы остановить рост растений"}],"correctAnswerId":"0","explanation":"Вода необходима живым организмам и пополняет водоёмы."}'::jsonb,'{"xp":10}'::jsonb),
('nature-1-10','nature-1','quiz',10,'{"question":"Что такое туман?","answers":[{"id":"0","text":"Множество очень маленьких капелек воды в воздухе у поверхности земли."},{"id":"1","text":"Облако из пыли"},{"id":"2","text":"Дым от деревьев"}],"correctAnswerId":"0","explanation":"Туман похож на облако, которое находится у поверхности земли."}'::jsonb,'{"xp":10}'::jsonb),
('nature-1-11','nature-1','quiz',11,'{"question":"Что происходит с водой при сильном замерзании?","answers":[{"id":"0","text":"Она превращается в лёд."},{"id":"1","text":"Она превращается в песок"},{"id":"2","text":"Она становится воздухом"}],"correctAnswerId":"0","explanation":"При замерзании жидкая вода переходит в твёрдое состояние — лёд."}'::jsonb,'{"xp":10}'::jsonb),
('nature-1-12','nature-1','quiz',12,'{"question":"Почему зимой многие растения растут медленнее?","answers":[{"id":"0","text":"Зимой холоднее и обычно меньше света."},{"id":"1","text":"Потому что растения забывают расти"},{"id":"2","text":"Потому что у растений исчезают корни"}],"correctAnswerId":"0","explanation":"Низкая температура и недостаток света замедляют рост многих растений."}'::jsonb,'{"xp":10}'::jsonb),
('nature-1-13','nature-1','quiz',13,'{"question":"Почему весной возвращаются перелётные птицы?","answers":[{"id":"0","text":"Становится теплее и появляется больше пищи."},{"id":"1","text":"Потому что зимой становится жарче"},{"id":"2","text":"Потому что птицы меняют цвет"}],"correctAnswerId":"0","explanation":"Весной условия снова становятся подходящими для питания и размножения."}'::jsonb,'{"xp":10}'::jsonb),
('nature-1-14','nature-1','quiz',14,'{"question":"Почему зимой вода в озере может превратиться в лёд?","answers":[{"id":"0","text":"При сильном охлаждении вода замерзает."},{"id":"1","text":"Потому что вода становится солёной"},{"id":"2","text":"Потому что озеро перестаёт двигаться"}],"correctAnswerId":"0","explanation":"Когда температура воды достигает точки замерзания, образуется лёд."}'::jsonb,'{"xp":10}'::jsonb),
('nature-1-15','nature-1','quiz',15,'{"question":"Почему весной на деревьях распускаются почки?","answers":[{"id":"0","text":"Становится теплее и появляется больше света."},{"id":"1","text":"Потому что зимой деревья получают больше света"},{"id":"2","text":"Потому что снег заставляет почки расти"}],"correctAnswerId":"0","explanation":"С наступлением подходящих условий дерево возобновляет рост."}'::jsonb,'{"xp":10}'::jsonb),
('nature-2-01','nature-2','quiz',1,'{"question":"Почему летом день длиннее, чем зимой?","answers":[{"id":"0","text":"Из-за наклона земной оси летом наша часть Земли дольше освещается Солнцем."},{"id":"1","text":"Потому что Земля летом вращается медленнее"},{"id":"2","text":"Потому что Солнце летом становится больше"}],"correctAnswerId":"0","explanation":"Наклон земной оси меняет продолжительность освещения в течение года."}'::jsonb,'{"xp":10}'::jsonb),
('nature-2-02','nature-2','quiz',2,'{"question":"Почему небо кажется голубым?","answers":[{"id":"0","text":"Солнечный свет рассеивается в атмосфере, и синий свет рассеивается сильнее других цветов."},{"id":"1","text":"Потому что в небе есть синяя вода"},{"id":"2","text":"Потому что облака отражают синюю краску"}],"correctAnswerId":"0","explanation":"Цвет неба связан с рассеянием солнечного света в атмосфере."}'::jsonb,'{"xp":10}'::jsonb),
('nature-2-03','nature-2','quiz',3,'{"question":"Почему летом обычно теплее, чем зимой?","answers":[{"id":"0","text":"Солнечные лучи падают на поверхность более прямо, а день длиннее."},{"id":"1","text":"Потому что Солнце приближается к Земле в июле"},{"id":"2","text":"Потому что зимой Земля перестаёт вращаться"}],"correctAnswerId":"0","explanation":"Сезонные изменения связаны прежде всего с наклоном земной оси и освещённостью."}'::jsonb,'{"xp":10}'::jsonb),
('nature-2-04','nature-2','quiz',4,'{"question":"Как появляется иней?","answers":[{"id":"0","text":"Водяной пар превращается в лёд на очень холодной поверхности."},{"id":"1","text":"Дождь превращается в песок"},{"id":"2","text":"Снег растёт на траве"}],"correctAnswerId":"0","explanation":"Иней образуется при замерзании водяного пара на холодных поверхностях."}'::jsonb,'{"xp":10}'::jsonb),
('nature-2-05','nature-2','quiz',5,'{"question":"Откуда утром берётся роса?","answers":[{"id":"0","text":"Ночью поверхность охлаждается, и водяной пар превращается в капельки воды."},{"id":"1","text":"Из капель дождя, которые падают только утром"},{"id":"2","text":"Из талого снега"}],"correctAnswerId":"0","explanation":"При охлаждении воздух и поверхность могут достигать температуры, при которой появляется роса."}'::jsonb,'{"xp":10}'::jsonb),
('nature-2-06','nature-2','quiz',6,'{"question":"Почему молнию видно раньше, чем слышно гром?","answers":[{"id":"0","text":"Свет распространяется намного быстрее звука."},{"id":"1","text":"Гром появляется позже молнии"},{"id":"2","text":"Молния находится ближе к земле"}],"correctAnswerId":"0","explanation":"Скорость света значительно выше скорости звука в воздухе."}'::jsonb,'{"xp":10}'::jsonb),
('nature-2-07','nature-2','quiz',7,'{"question":"Почему меняются времена года?","answers":[{"id":"0","text":"Из-за наклона земной оси и движения Земли вокруг Солнца."},{"id":"1","text":"Потому что Солнце каждый месяц меняет размер"},{"id":"2","text":"Потому что Земля останавливается зимой"}],"correctAnswerId":"0","explanation":"Наклон земной оси меняет количество солнечного света, получаемого разными частями Земли."}'::jsonb,'{"xp":10}'::jsonb),
('nature-2-08','nature-2','quiz',8,'{"question":"Почему летом насекомых обычно больше, чем зимой?","answers":[{"id":"0","text":"В тёплое время им легче находить пищу и размножаться."},{"id":"1","text":"Потому что зимой насекомые становятся крупнее"},{"id":"2","text":"Потому что летом у них появляется шерсть"}],"correctAnswerId":"0","explanation":"Температура и доступность пищи влияют на активность и размножение многих насекомых."}'::jsonb,'{"xp":10}'::jsonb),
('nature-2-09','nature-2','quiz',9,'{"question":"Почему у снежинок часто бывает шесть лучей?","answers":[{"id":"0","text":"При замерзании молекулы воды образуют структуру с шестикратной симметрией."},{"id":"1","text":"Потому что у всех облаков шесть сторон"},{"id":"2","text":"Потому что ветер рисует лучи"}],"correctAnswerId":"0","explanation":"Структура кристаллов льда приводит к характерной шестилучевой симметрии."}'::jsonb,'{"xp":10}'::jsonb),
('nature-2-10','nature-2','quiz',10,'{"question":"Почему утром осенью и весной может появляться туман?","answers":[{"id":"0","text":"Охлаждение воздуха у поверхности помогает водяному пару превратиться в мелкие капельки."},{"id":"1","text":"Потому что деревья выпускают дым"},{"id":"2","text":"Потому что туман падает с облаков как дождь"}],"correctAnswerId":"0","explanation":"Туман образуется, когда воздух около поверхности достигает высокой влажности и вода конденсируется."}'::jsonb,'{"xp":10}'::jsonb),
('nature-2-11','nature-2','quiz',11,'{"question":"Почему Солнце кажется нам разным по яркости?","answers":[{"id":"0","text":"На его видимую яркость влияют облака, время суток и положение над горизонтом."},{"id":"1","text":"Потому что Солнце выключается"},{"id":"2","text":"Потому что оно меняет размер каждый час"}],"correctAnswerId":"0","explanation":"Условия наблюдения меняются в течение дня и при разной облачности."}'::jsonb,'{"xp":10}'::jsonb),
('nature-2-12','nature-2','quiz',12,'{"question":"Что такое ледоход?","answers":[{"id":"0","text":"Движение льдин по реке во время весеннего таяния."},{"id":"1","text":"Падение снега на реку"},{"id":"2","text":"Замерзание моря летом"}],"correctAnswerId":"0","explanation":"Во время ледохода разрушившийся речной лёд движется вместе с течением."}'::jsonb,'{"xp":10}'::jsonb),
('nature-2-13','nature-2','quiz',13,'{"question":"Как образуется град?","answers":[{"id":"0","text":"В грозовом облаке капли воды замерзают и могут наращивать слои льда."},{"id":"1","text":"Снег плавится на земле и взлетает"},{"id":"2","text":"Роса превращается в камни"}],"correctAnswerId":"0","explanation":"Сильные восходящие потоки в грозовых облаках помогают льдинкам расти."}'::jsonb,'{"xp":10}'::jsonb),
('nature-2-14','nature-2','quiz',14,'{"question":"Почему летом бывают самые длинные дни?","answers":[{"id":"0","text":"В этот период Солнце дольше находится над горизонтом."},{"id":"1","text":"Потому что сутки становятся длиннее 24 часов"},{"id":"2","text":"Потому что Земля перестаёт вращаться"}],"correctAnswerId":"0","explanation":"Продолжительность светового дня меняется из-за наклона земной оси."}'::jsonb,'{"xp":10}'::jsonb),
('nature-2-15','nature-2','quiz',15,'{"question":"Как животные готовятся к зиме?","answers":[{"id":"0","text":"Одни запасают пищу, другие накапливают жир, меняют шерсть или впадают в зимний покой."},{"id":"1","text":"Все животные улетают на юг"},{"id":"2","text":"Все животные зимой не едят"}],"correctAnswerId":"0","explanation":"Разные виды используют разные приспособления к холодному сезону."}'::jsonb,'{"xp":10}'::jsonb),
('nature-3-01','nature-3','quiz',1,'{"question":"Что такое круговорот воды в природе?","answers":[{"id":"0","text":"Вода испаряется, образует облака, выпадает осадками и возвращается в водоёмы."},{"id":"1","text":"Вода исчезает после дождя"},{"id":"2","text":"Вода движется только под землёй"}],"correctAnswerId":"0","explanation":"Круговорот включает испарение, конденсацию, осадки и сток."}'::jsonb,'{"xp":10}'::jsonb),
('nature-3-02','nature-3','quiz',2,'{"question":"Почему на Земле разные климатические зоны?","answers":[{"id":"0","text":"Разные части Земли получают разное количество солнечного тепла."},{"id":"1","text":"Потому что все материки одинаково освещены"},{"id":"2","text":"Потому что климат зависит только от количества рек"}],"correctAnswerId":"0","explanation":"На климат влияют широта, солнечное тепло, высота, океаны и другие факторы."}'::jsonb,'{"xp":10}'::jsonb),
